def f(a: int, b: int) -> int:
    if 0 <= a <= 65535 and 1 <= b <= 8:
        # Extract the low b bits
        low_bits = a & ((1 << b) - 1)
        # If the MSB of the b-bit field is set, it's negative in 2's complement
        if low_bits & (1 << (b - 1)):
            return low_bits - (1 << b)
        else:
            return low_bits
    else:
        return -1
```

