def f(a: int, b: int) -> int:
    if not (0 <= a <= 65535 and 1 <= b <= 8):
        return -1
    mask = (1 << b) - 1
    x = a & mask
    if x >= (1 << (b - 1)):
        return x - (1 << b)
    return x
```

